CREATE POLICY "Users can view their own user-assets files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'user-assets' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Users can upload to their own user-assets folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'user-assets' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Users can update their own user-assets files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'user-assets' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'user-assets' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Users can delete their own user-assets files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'user-assets' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Service role can manage all user-assets files" ON storage.objects FOR ALL TO service_role USING (bucket_id = 'user-assets') WITH CHECK (bucket_id = 'user-assets');